import { assertTelemetryMode } from '../config/telemetryPolicy';
import path from 'path';
import { readCallerSessionModel } from '../cli/callerModel';
import { readHandshakeResult, isPidAlive } from '../cli/serverHandshake';
import { requestServer, type ServerResponse } from '../cli/client';
import {
  serverUnavailableResult,
  transportErrorResult,
} from '../cli/commands/shared';
import {
  withHostWorkNextAction,
  type StatusWithHostWork,
} from '../cli/hostWorkNextAction';
import { assertPluginContext } from '../hosts/pluginContext';
import { errorResult, okResult } from '../cli/envelope';
import { projectEditor } from '../cli/projectEditor';
import { getConfigManager } from '../services/ConfigManager';
import { ProjectLibrary } from '../services/ProjectLibrary';
import { VariantHistoryService } from '../services/VariantHistoryService';
import { nestedFreshSessionWorkdirs } from '../services/historyRoots';
import { isDirectionActive } from '../services/directionRefs';
import { listProjectDirections } from '../services/projectDirections';
import { withDesignProfiles } from './profileAccess';
import type { IntentResult } from './intentTool';

interface ExplorationSelection {
  project: string;
  sessionId?: string;
  variantId?: string;
  workId?: string;
  includeHistory?: boolean;
  callerAgent?: string;
  callerModel?: string;
}
export const getExploration = async (
  input: ExplorationSelection,
): Promise<IntentResult> => {
  const command = 'rivet_get_exploration';
  if (input.variantId && !input.sessionId)
    return {
      envelope: errorResult(
        command,
        'USAGE_ERROR',
        'variantId requires sessionId.',
      ).envelope,
    };
  const project = path.resolve(input.project);
  const found = readHandshakeResult(project);
  const hasLiveServer =
    found.status === 'found' && isPidAlive(found.handshake.pid);
  const data: Record<string, unknown> = { isLive: hasLiveServer };
  if (hasLiveServer) {
    assertPluginContext(found.handshake.pluginName);
    assertTelemetryMode(found.handshake.telemetryMode);
    const attached = {
      handshake: found.handshake,
      baseUrl: `http://127.0.0.1:${found.handshake.rivetPort}`,
    };
    let status: ServerResponse<StatusWithHostWork>;
    try {
      status = await requestServer<StatusWithHostWork>(
        attached,
        '/api/cli/status',
      );
    } catch (error) {
      return transportErrorResult(command, error);
    }
    if (status.status !== 200)
      return serverUnavailableResult({
        command,
        projectPath: project,
        reason: 'health_check_failed',
      });
    data.status = withHostWorkNextAction(status.body, {
      callerAgent: input.callerAgent,
      callerModel:
        input.callerModel ??
        (input.callerAgent === 'claude' || input.callerAgent === 'codex'
          ? readCallerSessionModel(input.callerAgent)
          : undefined),
    });
  }
  const library = ProjectLibrary.openReadOnly();
  let localHistory: VariantHistoryService | undefined;
  try {
    const owner = library?.registry.findByPath(project);
    data.editor = projectEditor({
      projectPath: project,
      ...(owner ? { projectId: owner.id } : {}),
    });
    const registered = library && owner ? { library, owner } : undefined;
    const history = registered
      ? await registered.library.history(registered.owner.id)
      : (localHistory = new VariantHistoryService());
    const roots = registered
      ? registered.library.registry.historyRoots(registered.owner.id)
      : [project, ...nestedFreshSessionWorkdirs(project)];
    if (!hasLiveServer || input.includeHistory || input.sessionId) {
      const directions = await listProjectDirections(
        registered
          ? {
              kind: 'library',
              library: registered.library,
              projectId: registered.owner.id,
            }
          : { kind: 'history', history, projectPath: project },
      );
      const entries = registered
        ? directions.filter((entry) => isDirectionActive(entry.manifest.status))
        : directions;
      data.history = entries.filter(
        (entry) =>
          (!input.sessionId || entry.manifest.sessionId === input.sessionId) &&
          (!input.variantId || entry.manifest.variantId === input.variantId),
      );
      if (input.variantId && input.sessionId) {
        const reference = {
          sessionId: input.sessionId,
          variantId: input.variantId,
        };
        data.direction = registered
          ? (
              await registered.library.variant({
                projectId: registered.owner.id,
                ...reference,
              })
            )?.detail
          : await history.getVariant({
              projectPath:
                entries.find(
                  (entry) =>
                    entry.manifest.sessionId === input.sessionId &&
                    entry.manifest.variantId === input.variantId,
                )?.projectPath ?? project,
              ...reference,
            });
        if (!data.direction)
          return {
            envelope: errorResult(
              command,
              'WORK_ITEM_NOT_FOUND',
              'The selected saved direction is unavailable.',
            ).envelope,
          };
      }
    }
    if (input.workId) {
      for (const projectPath of roots) {
        const receipt = await history.inspectGuidance({
          projectPath,
          workId: input.workId,
          accountId: getConfigManager().getUserId(),
        });
        data.instructions = receipt;
        if (receipt.isRecorded) break;
      }
    }
  } finally {
    library?.close();
    localHistory?.metadata.closeAll();
  }
  const workId = input.workId;
  if (workId) {
    const receipt = await withDesignProfiles(command, (profiles) =>
      profiles.inspect(workId),
    );
    data.references = receipt.envelope.ok
      ? {
          isRecorded: receipt.envelope.data !== null,
          receipt: receipt.envelope.data,
        }
      : { isRecorded: false, reason: receipt.envelope.error.code };
  }
  return { envelope: okResult(command, data).envelope };
};
